const cfg = $('Validation Configuration').first().json;

function parseItemIds(value) {
  if (Array.isArray(value)) return value.map(String);
  if (typeof value !== 'string' || !value.trim()) return [];
  const text = value.trim();
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed.map(String);
  } catch {}
  if (text.startsWith('{') && text.endsWith('}')) {
    return text.slice(1, -1).split(',').map(x => x.replace(/^"|"$/g, '').trim()).filter(Boolean);
  }
  return [];
}

function fnv1a(text) {
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

const offsets = [...new Set(String(cfg.sample_offsets).split(',')
  .map(x => Number(x.trim()))
  .filter(x => Number.isInteger(x) && x >= 0))].sort((a, b) => a - b);
const offsetsLabel = offsets.join(',');
const eligible = items
  .map(item => ({ ...item.json, item_ids: parseItemIds(item.json.item_ids) }))
  .filter(row => row.item_ids.length >= 2)
  .sort((a, b) => fnv1a(`${cfg.sample_seed}|${a.product_id}`) - fnv1a(`${cfg.sample_seed}|${b.product_id}`));
const productLimit = Number(cfg.sample_products) > 0 ? Number(cfg.sample_products) : eligible.length;
const selectedProducts = eligible.slice(0, productLimit);
const testedAt = new Date().toISOString();
const runId = `${cfg.dataset_key}|${cfg.sample_seed}|${testedAt}`;

return selectedProducts.flatMap(product => {
  const selectedItems = [...new Set(product.item_ids)]
    .sort((a, b) => fnv1a(`${cfg.sample_seed}|${product.product_id}|${a}`) - fnv1a(`${cfg.sample_seed}|${product.product_id}|${b}`))
    .slice(0, Number(cfg.items_per_product));
  return selectedItems.flatMap(item_id => offsets.map(offset => ({ json: {
    run_id: runId,
    tested_at: testedAt,
    dataset_key: cfg.dataset_key,
    sample_seed: cfg.sample_seed,
    sample_page_size: Number(cfg.sample_page_size),
    sample_offsets: offsetsLabel,
    product_id: product.product_id,
    item_id,
    offset
  }})));
});

const source = $('Build Reproducible Sample').all();
const probes = items.map((item, index) => {
  const input = source[index]?.json ?? {};
  const body = item.json ?? {};
  const reviews = Array.isArray(body.reviews) ? body.reviews : [];
  return {
    ...input,
    total: Number(body.paging?.total ?? 0),
    page_signature: reviews.map(r => String(r.id)).sort().join(','),
    error: body.error ?? body.message ?? null
  };
});

const productGroups = new Map();
for (const row of probes) {
  if (!productGroups.has(row.product_id)) productGroups.set(row.product_id, []);
  productGroups.get(row.product_id).push(row);
}

const output = [];
for (const [productId, productProbes] of productGroups) {
  const itemGroups = new Map();
  for (const probe of productProbes) {
    if (!itemGroups.has(probe.item_id)) itemGroups.set(probe.item_id, []);
    itemGroups.get(probe.item_id).push(probe);
  }
  const itemRows = [...itemGroups.entries()].map(([itemId, itemProbes]) => {
    itemProbes.sort((a, b) => a.offset - b.offset);
    return {
      ...itemProbes[0],
      item_id: itemId,
      total: Math.max(...itemProbes.map(p => p.total)),
      sampled_signature: itemProbes.map(p => `${p.offset}:${p.page_signature}`).join('|'),
      has_error: itemProbes.some(p => p.error)
    };
  });
  const validItems = itemRows.filter(r => !r.has_error);
  const withErrors = itemRows.length - validItems.length;
  const reference = validItems.find(r => r.total > 0) ?? validItems[0] ?? itemRows[0];
  const equivalent = validItems.filter(r => r.total === reference.total && r.sampled_signature === reference.sampled_signature).length;
  const withReviews = validItems.filter(r => r.total > 0).length;
  const withoutReviews = validItems.filter(r => r.total === 0).length;
  const distinctTotals = new Set(validItems.map(r => r.total)).size;
  const distinctSets = new Set(validItems.map(r => r.sampled_signature)).size;
  let verdict = 'DIFFERENT_REVIEW_SETS';
  if (withErrors > 0) verdict = 'INCONCLUSIVE_API_ERRORS';
  else if (withReviews === 0) verdict = 'NO_REVIEWS_RETURNED';
  else if (equivalent === itemRows.length) verdict = 'EQUIVALENT';
  else if (distinctSets <= 2 && withoutReviews > 0) verdict = 'EQUIVALENT_WITH_ZERO_EXCEPTIONS';
  output.push({ json: {
    run_id: reference.run_id, tested_at: reference.tested_at, dataset_key: reference.dataset_key,
    product_id: productId, sample_seed: reference.sample_seed, sample_page_size: reference.sample_page_size,
    sample_offsets: reference.sample_offsets, items_tested: itemRows.length, items_with_reviews: withReviews,
    items_without_reviews: withoutReviews, items_with_errors: withErrors, reference_item_id: reference.item_id, reference_total: reference.total,
    distinct_totals: distinctTotals, distinct_sampled_page_sets: distinctSets, equivalent_items: equivalent,
    equivalence_rate: validItems.length ? Number((100 * equivalent / validItems.length).toFixed(2)) : null, verdict
  }});
}
return output;
